Step.StepText:
Set Variable [ $candidates; Value:List ( Let ( [
  ~region = "Client Files - Western" ;
  ~L = Substitute ( BE_FileListFolder ( $liveRoot & ~region ; 2 ) ; [ Char ( 13 ) & Char ( 10 ) ; ¶ ] ; [ Char ( 10 ) ; ¶ ] )
] ;
While ( [ ~i = 0 ; ~out = "" ] ; ~i < ValueCount ( ~L ) ; [
    ~i = ~i + 1 ;
    ~letter = Let ( x = GetValue ( ~L ; ~i ) ; If ( Right ( x ; 1 ) = Char ( 92 ) ; Left ( x ; Length ( x ) - 1 ) ; x ) ) ;
    ~letter = If ( PatternCount ( ~letter ; Char ( 92 ) ) ; Right ( ~letter ; Length ( ~letter ) - Position ( ~letter ; Char ( 92 ) ; Length ( ~letter ) ; -1 ) ) ; ~letter ) ;
    ~K = If ( IsEmpty ( ~letter ) ; "" ; Substitute ( BE_FileListFolder ( $liveRoot & ~region & Char ( 92 ) & ~letter ; 2 ) ; [ Char ( 13 ) & Char ( 10 ) ; ¶ ] ; [ Char ( 10 ) ; ¶ ] ) ) ;
    ~out = List ( ~out ; While ( [ ~j = 0 ; ~o = "" ] ; ~j < ValueCount ( ~K ) ; [
        ~j = ~j + 1 ;
        ~kid = Let ( x = GetValue ( ~K ; ~j ) ; If ( Right ( x ; 1 ) = Char ( 92 ) ; Left ( x ; Length ( x ) - 1 ) ; x ) ) ;
    ~kid = If ( PatternCount ( ~kid ; Char ( 92 ) ) ; Right ( ~kid ; Length ( ~kid ) - Position ( ~kid ; Char ( 92 ) ; Length ( ~kid ) ; -1 ) ) ; ~kid ) ;
        ~o = If ( IsEmpty ( ~kid ) ; ~o ; List ( ~o ; ~region & Char ( 92 ) & ~letter & Char ( 92 ) & ~kid ) )
      ] ; ~o ) )
  ] ; ~out )
) ;
