    ~kid = If ( PatternCount ( ~kid ; Char ( 92 ) ) ; Right ( ~kid ; Length ( ~kid ) - Position ( ~kid ; Char ( 92 ) ; Length ( ~kid ) ; -1 ) ) ; ~kid ) ;
    ~out = If ( IsEmpty ( ~kid ) ; ~out ; List ( ~out ; ~region & Char ( 92 ) & ~kid ) )
  ] ; ~out )
) ) ]

