Step.StepText:
Set Variable [ $dups; Value:While ( [ ~i = 0 ; ~out = "" ] ; ~i < ValueCount ( $candidates ) ; [
    ~i = ~i + 1 ;
    ~rel = GetValue ( $candidates ; ~i ) ;
    ~notes = If ( Left ( ~rel ; 22 ) = "Client Files - Central" ; $liveRoot & ~rel ; $liveRoot & ~rel & Char ( 92 ) & "Session Notes" ) ;
    ~count = If ( IsEmpty ( ~rel ) or not BE_FileExists ( $archiveRoot & ~rel ) ; -1 ; ValueCount ( Substitute ( BE_FileListFolder ( ~notes ; 1 ) ; [ Char ( 13 ) & Char ( 10 ) ; ¶ ] ; [ Char ( 10 ) ; ¶ ] ) ) ) ;
    ~out = If ( ~count < 0 ; ~out ; List ( ~out ; ~rel & "   (" & ~count & " file" & If ( ~count = 1 ; "" ; "s" ) & " in the K: " & If ( Left ( ~rel ; 22 ) = "Client Files - Central" ; "folder" ; "Session Notes folder" ) & ")" ) )
  ] ; ~out ) ]

